import{_ as l,l as i,o as e,c as s,v as t,p as n,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"OLAP 立方","description":"","frontmatter":{"title":"OLAP 立方","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/olap-cube.md","filePath":"cs/olap-cube.md","lastUpdated":1789023840000}'),h={name:"cs/olap-cube.md"};function _(u,a,m,A,P,f){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="olap-立方" tabindex="-1">OLAP 立方 <a class="header-anchor" href="#olap-立方" aria-label="Permalink to &quot;OLAP 立方&quot;">​</a></h1><div class="epigraph"><p>把度量沿维的笛卡尔积预聚合，切片、切块、上卷、下钻就变成查已算好的格点，而不是每次扫事实表。</p><footer>—— 据 Gray et al., Data Cube, 1996；Codd 对 OLAP 的十二条；Kimball 立方与星型对照</footer></div><p><a href="/cs/star-schema">上一课</a>把分析查询收成窄事实加维。缺口是<strong>反复同一合计</strong>：每天按地区×产品×时间问 <code>SUM</code>。本课钉数据立方；湖仓下一课把表格式换成对象存储上的开放格式。不把立方写成「另一个 SQL」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(d\\) 维、每维基数 \\(n_i\\)，完整立方格点数随 \\(\\prod(n_i+1)\\) 涨（含 ALL）。物化全部会爆；物化太少则每次仍扫事实。缺口是选哪些视图（Harinarayan 等格子上的贪心）以及 MOLAP 数组 vs ROLAP 星型上的 SQL。与 GROUPING SETS / CUBE 语法：同一代数，不同存储。</p><p><span class="marginnote">Gray 等人的 CUBE 操作符把 GROUP BY 的幂集收成一个算子。稀疏事实使多数格点为空，存储必须压零。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选物化：按查询工作负载与空间预算。刷新：夜间批、或增量维护（与物化视图课同一机制）。查询改写：下钻走细粒度，上卷走已物化祖先。位图与列存加速剩余的即时聚合。</p>',8)),(e(),n(p,null,{default:r(()=>[c(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E4%BA%8B%E5%AE%9E%22%5D%20--%3E%20CUBE%5B%22%E9%80%89%E4%B8%AD%E7%9A%84%E6%A0%BC%E7%82%B9%22%5D%0A%20%20Q%5B%22%E5%88%87%E7%89%87%20%2F%20%E4%B8%8A%E5%8D%B7%22%5D%20--%3E%20CUBE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每个格点是一组 GROUP BY 属性上的聚合。祖先格点可由子孙再聚合当且仅当聚合可加（<code>SUM</code> 可，<code>AVG</code> 要存 count）。不可加度量必须存细粒度。稀疏格用数组压缩或干脆 ROLAP 当另一张汇总事实。查询改写命中物化点则不再扫明细；未命中则从更细格或星型事实现算——与 <a href="/cs/mv-refresh">物化视图刷新</a> 同一匹配思想。</p><p>位图与列存在切块过滤上加速剩余即时聚合。分布式构建立方时按维键 shuffle 一次，之后切片走本地。新鲜度：立方落后事实，合同写成 SLA，不要假装与 OLTP 同行可见。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Excel 透视表当实现，不写某 MOLAP 服务器目录。窗口函数不收缩成格点，不是立方。流上的时间窗口是未闭合的格，后课再钉。下一课湖仓：立方与明细都可以建在开放表快照上。</p><p>后课默认：热点上卷可物化立方；全格 \\(2^d\\) 不当默认。可加性没声明就不要从细算粗。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>立方是维上的预聚合格；物化集合是空间与延迟的折中。</li><li>可加性决定能否从细算粗；稀疏必须压零。</li><li>湖仓与开放表格式下一课。</li><li>出处：Gray et al., Data Cube, 1996；Kimball；Harinarayan 等视图选择。</li></ul>',8))])}const B=l(h,[["render",_]]);export{b as __pageData,B as default};
